const nav=[...document.querySelectorAll('.nav-links a')];const sections=nav.map(a=>document.querySelector(a.getAttribute('href'))).filter(Boolean);const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));const sio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){nav.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-35% 0px -55%'});sections.forEach(s=>sio.observe(s));document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>document.querySelector(b.dataset.scroll).scrollIntoView({behavior:'smooth'}));const cards=[...document.querySelectorAll('.ai-card')];let center=2;function rotate(d){center=(center+d+cards.length)%cards.length;cards.forEach((c,i)=>{c.classList.toggle('active',i===center);c.style.setProperty('--offset',((i-center+cards.length)%cards.length)>2?((i-center+cards.length)%cards.length)-cards.length:(i-center+cards.length)%cards.length)})}document.querySelector('.prev').onclick=()=>rotate(-1);document.querySelector('.next').onclick=()=>rotate(1);rotate(0);const lb=document.querySelector('#lightbox');document.querySelectorAll('.zoomable').forEach(b=>b.onclick=()=>{lb.querySelector('img').src=b.dataset.src;lb.showModal()});lb.querySelector('button').onclick=()=>lb.close();lb.onclick=e=>{if(e.target===lb)lb.close()};
